def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return: dict with days, seconds, microseconds or None if value is None
    """
    if value is None:
        return None
    try:
        # Attempt to extract the standard attributes of a timedelta
        days = getattr(value, "days")
        seconds = getattr(value, "seconds")
        microseconds = getattr(value, "microseconds")
        # Ensure the attributes are integers (typical for timedelta)
        if not all(isinstance(v, int) for v in (days, seconds, microseconds)):
            raise TypeError("timedelta attributes must be integers")
        return {"days": days, "seconds": seconds, "microseconds": microseconds}
    except AttributeError:
        raise TypeError("value must be a datetime.timedelta instance")
    except Exception as exc:
        raise RuntimeError(f"Error dehydrating timedelta: {exc}")

def dehydrate_time(value):
    """Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return: str or None
    """
    try:
        if value is None:
            return None
        import datetime
        if not isinstance(value, datetime.time):
            raise TypeError(f"Expected datetime.time, got {type(value).__name__}")
        # Use ISO 8601 format for consistency
        return value.isoformat()
    except Exception as exc:
        # Wrap any exception in a ValueError to signal dehydration failure
        raise ValueError(f"Error dehydrating time value: {exc}") from exc

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return: tuple of coordinates
    """
    try:
        if value is None:
            raise ValueError("Input value is None")

        # Handle tuple or list with 2 or 3 elements
        if isinstance(value, (tuple, list)):
            if len(value) not in (2, 3):
                raise ValueError("Tuple/list must contain 2 or 3 elements")
            return tuple(value)

        # Handle objects with x, y (and optionally z) attributes
        if hasattr(value, "x") and hasattr(value, "y"):
            coords = [value.x, value.y]
            if hasattr(value, "z"):
                coords.append(value.z)
            return tuple(coords)

        # Handle iterable objects that yield 2 or 3 items
        try:
            items = list(value)
            if len(items) in (2, 3):
                return tuple(items)
        except TypeError:
            pass

        raise TypeError("Unsupported type for dehydrate_point")
    except Exception as exc:
        raise ValueError(f"Error dehydrating point: {exc}") from exc

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        # Attempt to retrieve the underlying data container
        if hasattr(self, "_data"):
            data = getattr(self, "_data")
        elif hasattr(self, "data"):
            data = getattr(self, "data")
        else:
            # Fallback to the instance's __dict__
            data = self.__dict__

        # If the data is None or not a mapping, return an empty list
        if data is None:
            return []

        # If it's a dictionary, return its keys
        if isinstance(data, dict):
            return list(data.keys())

        # If it's an object with a __dict__, use that
        if hasattr(data, "__dict__"):
            return list(data.__dict__.keys())

        # If none of the above, we cannot determine keys
        return []
    except Exception:
        # In case of any unexpected error, return an empty list
        return []

def index(self, key):
    """
    Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    # Attempt to iterate over the object. If it is not iterable, raise a clear error.
    try:
        for idx, item in enumerate(self):
            if item == key:
                return idx
    except TypeError:
        raise TypeError(f"{self.__class__.__name__} object is not iterable and cannot be searched for a key")

    # If we get here, the key was not found.
    raise ValueError(f"{key!r} is not in {self.__class__.__name__}")

def values(self, *keys):
    """Return the values of the record, optionally filtering to include only certain values by index or key."""
    # Determine if the object behaves like a mapping or a sequence
    is_mapping = hasattr(self, "keys") and callable(getattr(self, "keys"))
    is_sequence = hasattr(self, "__getitem__") and hasattr(self, "__len__")
    if not (is_mapping or is_sequence):
        raise TypeError("Object does not support mapping or sequence operations")

    # If no keys are provided, return all values
    if not keys:
        if is_mapping:
            return list(self.values())
        else:
            return list(self)

    # Collect the requested values
    result = []
    for key in keys:
        try:
            if is_mapping:
                # Treat key as a mapping key
                result.append(self[key])
            else:
                # Treat key as an index into the sequence
                result.append(self[key])
        except KeyError as e:
            raise KeyError(f"Key {key!r} not found") from e
        except IndexError as e:
            raise IndexError(f"Index {key!r} out of range") from e
        except Exception as e:
            raise TypeError(f"Unsupported key type {type(key).__name__}") from e
    return result

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    try:
        if not hasattr(self, "data"):
            raise AttributeError("Missing 'data' attribute")
        if len(self.data) < 2:
            raise ValueError("Insufficient data: need at least 2 bytes to pop a u16")
        # Pop the last two bytes (low byte first, then high byte)
        low = self.data.pop()
        high = self.data.pop()
        # Combine into a big-endian 16-bit integer
        return (high << 8) | low
    except Exception as exc:
        raise RuntimeError(f"Failed to pop u16: {exc}") from exc

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
              db=None, imp_user=None, dehydration_hooks=None,
              hydration_hooks=None, **handlers):
        """
        Appends a BEGIN message to the output queue.

        :param mode: access mode for routing - "READ" or "WRITE" (default)
        :param bookmarks: iterable of bookmark values after which this transaction should begin
        :param metadata: custom metadata dictionary to attach to the transaction
        :param timeout: timeout for transaction execution (seconds)
        :param db: name of the database against which to begin the transaction
            Requires Bolt 4.0+.
        :param imp_user: the user to impersonate
            Requires Bolt 4.4+
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            dehydration function). Dehydration functions receive the value of
            type understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        :return: Response object
        """
        # Validate mode
        if mode is not None:
            if not isinstance(mode, str):
                raise TypeError(f"mode must be a string, got {type(mode).__name__}")
            mode_upper = mode.upper()
            if mode_upper not in ("READ", "WRITE"):
                raise ValueError(f"mode must be 'READ' or 'WRITE', got {mode!r}")
            mode = mode_upper

        # Validate bookmarks
        if bookmarks is not None:
            try:
                iter(bookmarks)
            except TypeError:
                raise TypeError("bookmarks must be an iterable of strings")
            # Ensure all items are strings
            for bm in bookmarks:
                if not isinstance(bm, str):
                    raise TypeError(f"each bookmark must be a string, got {type(bm).__name__}")

        # Validate metadata
        if metadata is not None and not isinstance(metadata, dict):
            raise TypeError(f"metadata must be a dict, got {type(metadata).__name__}")

        # Validate timeout
        if timeout is not None:
            if not isinstance(timeout, (int, float)):
                raise TypeError(f"timeout must be a number, got {type(timeout).__name__}")
            if timeout < 0:
                raise ValueError("timeout must be non-negative")

        # Validate db
        if db is not None and not isinstance(db, str):
            raise TypeError(f"db must be a string, got {type(db).__name__}")

        # Validate imp_user
        if imp_user is not None and not isinstance(imp_user, str):
            raise TypeError(f"imp_user must be a string, got {type(imp_user).__name__}")

        # Validate dehydration_hooks
        if dehydration_hooks is not None:
            if not isinstance(dehydration_hooks, dict):
                raise TypeError(f"dehydration_hooks must be a dict, got {type(dehydration_hooks).__name__}")
            for key, func in dehydration_hooks.items():
                if not isinstance(key, type):
                    raise TypeError(f"dehydration_hooks keys must be types, got {type(key).__name__}")
                if not callable(func):
                    raise TypeError(f"dehydration_hooks values must be callables, got {type(func).__name__}")

        # Validate hydration_hooks
        if hydration_hooks is not None:
            if not isinstance(hydration_hooks, dict):
                raise TypeError(f"hydration_hooks must be a dict, got {type(hydration_hooks).__name__}")
            for key, func in hydration_hooks.items():
                if not isinstance(key, type):
                    raise TypeError(f"hydration_hooks keys must be types, got {type(key).__name__}")
                if not callable(func):
                    raise TypeError(f"hydration_hooks values must be callables, got {type(func).__name__}")

        # Prepare the BEGIN message
        message = {
            "type": "BEGIN",
            "mode": mode,
            "bookmarks": list(bookmarks) if bookmarks is not None else None,
            "metadata": metadata,
            "timeout": timeout,
            "db": db,
            "imp_user": imp_user,
            "dehydration_hooks": dehydration_hooks,
            "hydration_hooks": hydration_hooks
        }

        # Append to the output queue
        try:
            self._output_queue.append(message)
        except AttributeError as exc:
            raise RuntimeError("Output queue not initialized on this connection") from exc

        # Return a Response object, passing any handlers
        try:
            return Response(self, **handlers)
        except Exception as exc:
            # If Response construction fails, raise a generic error
            raise RuntimeError("Failed to create Response object") from exc

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")
    if not isinstance(ttl, (int, float)) or ttl <= 0:
        raise ValueError("ttl must be a positive number")
    if not callable(timer):
        raise TypeError("timer must be a callable returning a monotonic time")

    def decorator(func):
        cache = {}
        order = []

        def make_key(args, kwargs):
            key = args
            if kwargs:
                # Sort kwargs to ensure consistent ordering
                key += tuple(sorted(kwargs.items()))
            if typed:
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))
            return key

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            now = timer()
            # Clean up expired entry if present
            if key in cache:
                value, expire = cache[key]
                if expire <= now:
                    # expired
                    del cache[key]
                    order.remove(key)
                else:
                    # move to end to mark as recently used
                    order.remove(key)
                    order.append(key)
                    return value
            # compute new value
            try:
                result = func(*args, **kwargs)
            except Exception:
                # Do not cache exceptions
                raise
            expire_time = now + ttl
            # Insert into cache
            cache[key] = (result, expire_time)
            order.append(key)
            # Evict if over maxsize
            if len(order) > maxsize:
                oldest = order.pop(0)
                del cache[oldest]
            return result

        return wrapper

    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if not isinstance(maxsize, int) or maxsize < 0:
        raise ValueError("maxsize must be a non-negative integer")
    from functools import wraps
    from collections import OrderedDict, namedtuple

    def decorating_function(user_function):
        cache = OrderedDict()
        hits = misses = 0

        @wraps(user_function)
        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            # Build key
            try:
                if typed:
                    key = args + tuple(type(v) for v in args)
                    key += tuple(sorted(kwargs.items())) + tuple(type(v) for v in kwargs.values())
                else:
                    key = args + tuple(sorted(kwargs.items()))
            except TypeError:
                # Unhashable arguments; bypass cache
                return user_function(*args, **kwargs)

            if key in cache:
                # Move to end to mark as most recently used
                cache.move_to_end(key)
                hits += 1
                return cache[key]
            else:
                misses += 1
                result = user_function(*args, **kwargs)
                cache[key] = result
                # Move to end to mark as most recently used
                cache.move_to_end(key)
                if maxsize and len(cache) > maxsize:
                    # Evict most recently used item
                    cache.popitem(last=True)
                return result

        def cache_info():
            """Report cache statistics"""
            CacheInfo = namedtuple('CacheInfo', ['hits', 'misses', 'maxsize', 'currsize'])
            return CacheInfo(hits, misses, maxsize, len(cache))

        def cache_clear():
            """Clear the cache and cache statistics"""
            nonlocal hits, misses
            cache.clear()
            hits = misses = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper

    return decorating_function

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    # Validate parameters
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")
    if not isinstance(typed, bool):
        raise TypeError("typed must be a boolean")

    def decorator(func):
        if not callable(func):
            raise TypeError("lru_cache can only be applied to callable objects")

        cache = {}
        order = []

        def wrapper(*args, **kwargs):
            # Build cache key
            try:
                if typed:
                    key = (args,
                           tuple(sorted(kwargs.items())),
                           tuple(type(arg) for arg in args),
                           tuple(type(v) for v in kwargs.values()))
                else:
                    key = (args, tuple(sorted(kwargs.items())))
            except Exception as e:
                # If arguments are not hashable, fall back to no caching
                return func(*args, **kwargs)

            if key in cache:
                # Move key to the end to mark it as recently used
                order.remove(key)
                order.append(key)
                return cache[key]

            # Compute the result and store it
            result = func(*args, **kwargs)
            cache[key] = result
            order.append(key)

            # Enforce maxsize
            if len(order) > maxsize:
                oldest = order.pop(0)
                cache.pop(oldest, None)

            return result

        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")
    if not isinstance(typed, bool):
        raise TypeError("typed must be a boolean")

    def decorator(func):
        cache = {}
        counts = {}
        insertion = {}
        next_index = 0
        try:
            from functools import wraps
        except Exception:
            # Fallback if functools is unavailable
            def wraps(f):
                return f

        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal next_index
            try:
                if typed:
                    key = (
                        args,
                        tuple(sorted(kwargs.items())),
                        tuple(type(arg) for arg in args),
                        tuple(type(v) for k, v in sorted(kwargs.items())),
                    )
                else:
                    key = (args, tuple(sorted(kwargs.items())))
            except TypeError as e:
                raise TypeError(f"Unhashable arguments for caching: {e}") from e

            if key in cache:
                counts[key] += 1
                return cache[key]

            result = func(*args, **kwargs)

            cache[key] = result
            counts[key] = 1
            insertion[key] = next_index
            next_index += 1

            if len(cache) > maxsize:
                # Find the key with the lowest count; break ties by earliest insertion
                min_key = None
                min_count = None
                min_insertion = None
                for k in cache:
                    c = counts[k]
                    if (
                        min_count is None
                        or c < min_count
                        or (c == min_count and insertion[k] < min_insertion)
                    ):
                        min_count = c
                        min_key = k
                        min_insertion = insertion[k]
                if min_key is not None:
                    del cache[min_key]
                    del counts[min_key]
                    del insertion[min_key]

            return result

        return wrapper

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        key = next(iter(self))
    except StopIteration:
        raise KeyError("popitem(): dictionary is empty")
    except Exception as e:
        raise RuntimeError(f"Error retrieving first key: {e}") from e
    try:
        value = self[key]
        del self[key]
    except Exception as e:
        raise RuntimeError(f"Error removing key {key!r}: {e}") from e
    return key, value

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    try:
        if key in self:
            return self[key]
        self[key] = default
        return default
    except TypeError as exc:
        raise TypeError(f"Invalid key {key!r}: {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Error setting default for key {key!r}: {exc}") from exc

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    try:
        return self[key]
    except KeyError:
        return default
    except Exception:
        # Handles cases where key is unhashable or self is not a proper mapping
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    if cache is None:
        raise ValueError("cache argument must not be None")
    if key is None:
        raise ValueError("key argument must not be None")

    def decorator(func):
        def wrapper(*args, **kwargs):
            # Compute cache key
            try:
                k = key(*args, **kwargs)
            except Exception:
                try:
                    k = key(func, *args, **kwargs)
                except Exception:
                    # Fallback: use a hash of the function name and arguments
                    try:
                        k = hash((func.__name__, args, tuple(sorted(kwargs.items()))))
                    except Exception:
                        # As a last resort, use id of args tuple
                        k = id((args, tuple(kwargs.items())))

            # Acquire lock if provided
            if lock:
                try:
                    lock.acquire()
                except Exception:
                    # If lock acquisition fails, proceed without locking
                    pass

            try:
                # Attempt to retrieve from cache
                try:
                    if k in cache:
                        return cache[k]
                except Exception:
                    # If 'in' fails, try get
                    try:
                        cached_val = cache.get(k)
                        if cached_val is not None:
                            return cached_val
                    except Exception:
                        pass

                # Compute result and store in cache
                result = func(*args, **kwargs)
                try:
                    cache[k] = result
                except Exception:
                    # If cache assignment fails, ignore caching
                    pass
                return result
            finally:
                # Release lock if it was acquired
                if lock:
                    try:
                        lock.release()
                    except Exception:
                        pass

        # Preserve function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper

    return decorator

@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception into a readable string with limited stack depth and path depth.
    """
    if not isinstance(e, BaseException):
        raise TypeError("e must be an exception instance")
    try:
        import traceback, os
    except Exception:
        # Fallback if imports fail
        traceback = None
        os = None

    # Build the main exception message
    parts = [f"{e.__class__.__name__}: {e}"]

    # Extract traceback frames if available
    tb = getattr(e, "__traceback__", None)
    if tb and traceback:
        stack = traceback.extract_tb(tb)
        # Limit to the last `max_level` frames
        if len(stack) > max_level:
            stack = stack[-max_level:]
        for frame in stack:
            filename = frame.filename
            if os:
                # Truncate path to the last `max_path_level` components
                parts_path = filename.split(os.sep)
                if len(parts_path) > max_path_level:
                    filename = os.sep.join(parts_path[-max_path_level:])
            parts.append(f"  File \"{filename}\", line {frame.lineno}, in {frame.name}")
            if frame.line:
                parts.append(f"    {frame.line.strip()}")
    else:
        parts.append("  No traceback available")

    # Handle chained exceptions (__cause__ and __context__)
    def _format_chain(exc, prefix="Caused by"):
        if exc is None:
            return
        parts.append(f"{prefix} {exc.__class__.__name__}: {exc}")
        tb = getattr(exc, "__traceback__", None)
        if tb and traceback:
            stack = traceback.extract_tb(tb)
            if len(stack) > max_level:
                stack = stack[-max_level:]
            for frame in stack:
                filename = frame.filename
                if os:
                    parts_path = filename.split(os.sep)
                    if len(parts_path) > max_path_level:
                        filename = os.sep.join(parts_path[-max_path_level:])
                parts.append(f"  File \"{filename}\", line {frame.lineno}, in {frame.name}")
                if frame.line:
                    parts.append(f"    {frame.line.strip()}")
        # Recurse into deeper chains
        _format_chain(exc.__cause__, prefix="Caused by")
        _format_chain(exc.__context__, prefix="During handling of the above exception")

    _format_chain(e.__cause__)
    _format_chain(e.__context__)

    return "\n".join(parts)

@staticmethod
    def is_file_exist(file_name):
        """
        Check if file name exist.
        :param file_name: File name.
        :type file_name: str
