def _getTargetClass(self):
        """
        Define this to return the implementation in use,
        without the 'Py' or 'Fallback' suffix.
        """
        try:
            impl = getattr(self, "_impl", None)
            if impl is None:
                raise ValueError("Implementation attribute '_impl' is not set.")
            if not isinstance(impl, str):
                raise TypeError(f"Expected '_impl' to be a string, got {type(impl).__name__}.")
            if impl.endswith("Py"):
                return impl[:-2]
            if impl.endswith("Fallback"):
                return impl[:-8]
            return impl
        except Exception as exc:
            raise RuntimeError(f"Failed to determine target class: {exc}") from exc

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    if not isinstance(all, bool):
        raise TypeError("Parameter 'all' must be a boolean.")
    result = {}
    # Collect non-callable attributes (excluding private ones)
    for name in dir(self):
        if name.startswith("_"):
            continue
        try:
            attr = getattr(self, name)
        except Exception:
            continue
        if callable(attr):
            continue
        # Handle property objects specially
        if isinstance(attr, property):
            desc = getattr(attr.fget, "__doc__", "") if attr.fget else ""
        else:
            desc = getattr(attr, "__doc__", "")
        if desc is None:
            desc = ""
        result[name] = desc
    # If requested, also include callable members (methods, functions, etc.)
    if all:
        for name in dir(self):
            if name.startswith("_"):
                continue
            try:
                attr = getattr(self, name)
            except Exception:
                continue
            if not callable(attr):
                continue
            if isinstance(attr, property):
                desc = getattr(attr.fget, "__doc__", "") if attr.fget else ""
            else:
                desc = getattr(attr, "__doc__", "")
            if desc is None:
                desc = ""
            result[name] = desc
    return result

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
