    if sequence is None:
        raise TypeError("sequence cannot be None")
    # Strings and bytes are considered atomic, not iterable for this purpose
    if isinstance(sequence, (str, bytes)):
        raise TypeError("sequence must be an iterable of arguments")

    # Helper to recursively process items
    def _process(item):
        # If item is a tuple or list, expand it recursively
        if isinstance(item, (list, tuple)):
            for sub in item:
                _process(sub)
        else:
            # Atomic item (interface, implements spec, or other)
            output.append(item)

    try:
        for elem in sequence:
            _process(elem)
    except TypeError as exc:
        # Raised if sequence is not iterable
        raise TypeError("sequence must be an iterable of arguments") from exc

    return output

def _should_attempt_c_optimizations():
    """
    Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    try:
        import os
        import platform
    except Exception:
        # If we cannot import required modules, be conservative and do not attempt C optimizations
        return False

    # Do not attempt C optimizations on PyPy, as C extensions may not be supported
    try:
        if platform.python_implementation() == "PyPy":
            return False
    except Exception:
        # If we cannot determine the implementation, be conservative
        return False

    # Check the PURE_PYTHON environment variable
    try:
        pure_python = os.getenv("PURE_PYTHON")
    except Exception:
        pure_python = None

    if pure_python is not None:
        # Interpret common truthy values; any other set value is considered truthy
        # and disables C optimizations. Values that explicitly indicate false
        # (e.g., "0", "false", "no", "off") allow C optimizations.
        val = pure_python.strip().lower()
        if val not in ("0", "false", "no", "off"):
            return False

    # Default: attempt C optimizations
    return True

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    try:
        required = _c_optimizations_required()
    except Exception:
        # If the required function is missing or raises an error, assume optimizations are not required
        return True
    return not bool(required)

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        return not bool(PURE_PYTHON)
    except NameError:
        # If PURE_PYTHON is not defined, assume C optimizations are required
        return True

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    try:
        # Reset the current context
        self._context = {}

        # Reinitialize bins
        if hasattr(self, "_initial_value") and self._initial_value is not None:
            self._bins = self._initial_value
        else:
            # Fallback to make_bins if available
            if hasattr(self, "make_bins") and callable(self.make_bins):
                self._bins = self.make_bins()
            else:
                raise AttributeError("No initial_value or make_bins method available to reinitialize bins.")
    except Exception as exc:
        raise RuntimeError(f"Failed to reset histogram: {exc}") from exc

def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    # Validate separator
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")
    # Validate header
    if header is not None and not isinstance(header, str):
        raise TypeError("header must be a string or None")

    lines = []
    if header is not None:
        lines.append(header)

    try:
        points = getattr(self, "points", None)
        if points is None:
            raise AttributeError("Graph object has no 'points' attribute")

        for point in points:
            # Expect point to be a tuple/list of (coordinate, value)
            if not isinstance(point, (list, tuple)) or len(point) != 2:
                continue
            coord, value = point

            # Convert coordinate to string
            if isinstance(coord, (list, tuple)):
                coord_str = separator.join(map(str, coord))
            else:
                coord_str = str(coord)

            # Convert value to string
            if isinstance(value, (list, tuple)):
                value_str = separator.join(map(str, value))
            else:
                value_str = str(value)

            lines.append(f"{coord_str}{separator}{value_str}")

    except Exception as exc:
        raise RuntimeError(f"Failed to convert graph to CSV: {exc}") from exc

    return "\n".join(lines)

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    try:
        # Ensure inputs are iterable
        bins_list = list(bins)
        edges_list = list(edges)

        if len(edges_list) != len(bins_list) + 1:
            raise ValueError(
                "Length of edges must be one more than length of bins."
            )

        # Compute bin widths
        widths = []
        for i in range(len(bins_list)):
            try:
                w = float(edges_list[i + 1]) - float(edges_list[i])
            except Exception as exc:
                raise ValueError(
                    f"Invalid edge values at positions {i} and {i+1}: {exc}"
                ) from exc
            widths.append(w)

        # Compute integral as sum of bin values times widths
        total = 0.0
        for b, w in zip(bins_list, widths):
            try:
                total += float(b) * w
            except Exception as exc:
                raise ValueError(f"Invalid bin value {b}: {exc}") from exc

        return total
    except Exception as exc:
        raise ValueError(f"Error computing integral: {exc}") from exc

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'request', None))
    except Exception:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        return callable(getattr(obj, 'run', None))
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        return callable(getattr(obj, 'fill')) and callable(getattr(obj, 'compute'))
    except Exception:
        return False

def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Validate weight
    try:
        weight = float(weight)
    except Exception:
        raise ValueError("weight must be a numeric value")

    # Convert coord to a 1‑D array
    try:
        coord_arr = np.asarray(coord, dtype=float)
    except Exception:
        raise ValueError("coord must be array‑like")

    if coord_arr.ndim != 1:
        raise ValueError("coord must be a 1‑D array of length equal to histogram dimensions")

    # Determine number of dimensions
    if hasattr(self, "ndim"):
        ndim = self.ndim
    else:
        if hasattr(self, "edges"):
            ndim = len(self.edges)
        else:
            raise AttributeError("Histogram object must have 'edges' or 'ndim' attribute")

    if coord_arr.size != ndim:
        raise ValueError(f"coord length ({coord_arr.size}) does not match histogram dimensions ({ndim})")

    # Ensure edges are available
    if not hasattr(self, "edges"):
        raise AttributeError("Histogram object must have 'edges' attribute")

    # Find bin indices for each dimension
    bin_indices = []
    for dim, (c, edge) in enumerate(zip(coord_arr, self.edges)):
        if edge is None or len(edge) == 0:
            raise ValueError(f"Edge array for dimension {dim} is invalid")
        # Use searchsorted to find the right bin
        idx = np.searchsorted(edge, c, side="right") - 1
        # Check if coordinate is inside the histogram bounds
        if idx < 0 or idx >= len(edge) - 1:
            # Outside the histogram; ignore
            return
        bin_indices.append(idx)

    # Increment the appropriate bin
    try:
        self.data[tuple(bin_indices)] += weight
    except Exception as exc:
        raise RuntimeError(f"Failed to fill histogram: {exc}")

def validate_value(value):
    """Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    try:
        if not isinstance(value, str):
            raise ValidationError("Value must be a string")
        if not value:
            raise ValidationError("Value cannot be empty")
        # Simple alphanumeric check as a placeholder for the intended regex
        if not value.isalnum():
            raise ValidationError("Value must contain only alphanumeric characters")
    except ValidationError:
        raise
    except Exception as exc:
        raise ValidationError(f"Unexpected error during validation: {exc}") from exc

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:`generate_default_observer_schema_list`, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError(f"manifest_dict must be a dict, got {type(manifest_dict).__name__}")
    if not isinstance(first_level, bool):
        raise TypeError(f"first_level must be a bool, got {type(first_level).__name__}")

    result = {}
    identifying_fields = {"apiVersion", "kind", "metadata"}

    for key, value in manifest_dict.items():
        # Copy identifying fields unchanged when at the top level
        if first_level and key in identifying_fields:
            result[key] = value
            continue

        if isinstance(value, dict):
            # Recurse into nested dictionaries
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Recurse into lists; assume helper exists
            try:
                result[key] = generate_default_observer_schema_list(value)
            except NameError as e:
                raise RuntimeError(
                    "generate_default_observer_schema_list is not defined. "
                    "Ensure it is implemented in the same module."
                ) from e
        else:
            # Replace scalar values with None
            result[key] = None

    return result

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A mapping from a resource identifier (kind/namespace/name) to a default
        observer schema dictionary. Resources that already specify a custom observer
        schema are omitted.
    """
    # Validate input
    if app is None:
        raise ValueError("app must not be None")

    # Attempt to retrieve the manifest list
    try:
        spec = getattr(app, "spec", None)
        if spec is None:
            raise AttributeError("app.spec is missing")
        manifest = getattr(spec, "manifest", None)
        if manifest is None:
            raise AttributeError("app.spec.manifest is missing")
    except Exception as exc:
        raise ValueError(f"Invalid app object: {exc}") from exc

    if not isinstance(manifest, (list, tuple)):
        raise ValueError("app.spec.manifest must be a list or tuple of resources")

    default_schemas = {}
    for resource in manifest:
        if not isinstance(resource, dict):
            # Skip non-dict entries
            continue

        # Skip resources that already define a custom observer schema
        # The custom schema is expected to be under resource['spec']['observer_schema']
        spec_section = resource.get("spec", {})
        if isinstance(spec_section, dict) and "observer_schema" in spec_section:
            continue

        # Extract required fields with defaults
        api_version = resource.get("apiVersion", "")
        kind = resource.get("kind", "")
        metadata = resource.get("metadata", {})
        if not isinstance(metadata, dict):
            metadata = {}
        name = metadata.get("name", "")
        namespace = metadata.get("namespace", "default")

        # Build a unique key for the resource
        key = f"{kind}/{namespace}/{name}"

        # Construct a minimal default observer schema
        default_schema = {
            "apiVersion": api_version,
            "kind": kind,
            "metadata": {
                "name": name,
                "namespace": namespace,
            },
        }

        default_schemas[key] = default_schema

    return default_schemas

