def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Ensure path is a string or Path-like
        if path is None:
            return False
        # Convert to string if needed
        if hasattr(path, "as_posix"):
            path = path.as_posix()
        else:
            path = str(path)

        # Path must exist and be a directory
        if not os.path.isdir(path):
            return False

        # OCFL root should contain an 'objects' directory
        objects_dir = os.path.join(path, "objects")
        if not os.path.isdir(objects_dir):
            return False

        # Each object directory must contain a 'manifest' file and a 'content' directory
        for obj_id in os.listdir(objects_dir):
            obj_path = os.path.join(objects_dir, obj_id)
            if not os.path.isdir(obj_path):
                continue  # skip non-directories

            manifest_path = os.path.join(obj_path, "manifest")
            content_dir = os.path.join(obj_path, "content")

            if not os.path.isfile(manifest_path):
                # Warning: missing manifest, but still consider valid
                continue
            if not os.path.isdir(content_dir):
                # Warning: missing content directory, but still consider valid
                continue

        # If we reach here, the structure is at least minimally valid
        return True
    except Exception:
        # Any unexpected error results in invalid
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    try:
        # Ensure prefix is a string
        prefix = '' if prefix is None else str(prefix)

        # Determine validity flag
        if hasattr(self, 'is_valid'):
            is_valid = bool(self.is_valid)
        elif hasattr(self, 'valid'):
            is_valid = bool(self.valid)
        else:
            is_valid = None

        parts = [prefix] if prefix else []

        if is_valid is None:
            parts.append("Status unknown")
        else:
            parts.append("Valid" if is_valid else "Invalid")

        # Include error count if available
        if hasattr(self, 'errors'):
            try:
                err = self.errors
                if isinstance(err, (list, tuple, set)):
                    err_count = len(err)
                elif isinstance(err, dict):
                    err_count = len(err)
                else:
                    err_count = 1
                if err_count:
                    parts.append(f"Errors: {err_count}")
            except Exception:
                pass

        # Include warning count if available
        if hasattr(self, 'warnings'):
            try:
                warn = self.warnings
                if isinstance(warn, (list, tuple, set)):
                    warn_count = len(warn)
                elif isinstance(warn, dict):
                    warn_count = len(warn)
                else:
                    warn_count = 1
                if warn_count:
                    parts.append(f"Warnings: {warn_count}")
            except Exception:
                pass

        return ' | '.join(parts)
    except Exception as e:
        return f"{prefix}Error retrieving status: {e}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    try:
        if not isinstance(prefix, str):
            raise TypeError("prefix must be a string")
        # Retrieve the log; default to empty list if not present
        log = getattr(self, 'log', [])
        # Ensure the log is iterable
        if not hasattr(log, '__iter__'):
            raise TypeError("log attribute is not iterable")
        # Build the string representation
        lines = []
        for entry in log:
            try:
                entry_str = str(entry)
            except Exception:
                entry_str = "<unrepresentable entry>"
            lines.append(f"{prefix}{entry_str}")
        return "\n".join(lines)
    except Exception as exc:
        # Return a clear error message instead of propagating the exception
        return f"Error generating status string: {exc}"

def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type check for inventory
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")

    # Determine spec_version from the inventory type if requested
    if extract_spec_version:
        type_val = inventory.get("type")
        if isinstance(type_val, str):
            # Map known type values to spec versions
            type_to_version = {
                "typeA": "1.0",
                "typeB": "2.0",
                "typeC": "3.0",
            }
            if type_val in type_to_version:
                self.spec_version = type_to_version[type_val]

    # Ensure required top‑level keys exist
    required_keys = ["name", "items"]
    for key in required_keys:
        if key not in inventory:
            raise ValueError(f"Missing required key: {key}")

    # Validate the items list
    items = inventory["items"]
    if not isinstance(items, list):
        raise TypeError("inventory['items'] must be a list")

    # Perform spec_version‑specific validation
    if self.spec_version == "1.0":
        for idx, item in enumerate(items):
            if not isinstance(item, dict):
                raise TypeError(f"Item at index {idx} must be a dict for spec 1.0")
            if "id" not in item:
                raise ValueError(f"Item at index {idx} missing 'id' key for spec 1.0")
    elif self.spec_version == "2.0":
        for idx, item in enumerate(items):
            if not isinstance(item, dict):
                raise TypeError(f"Item at index {idx} must be a dict for spec 2.0")
            if "uuid" not in item:
                raise ValueError(f"Item at index {idx} missing 'uuid' key for spec 2.0")
    elif self.spec_version == "3.0":
        # Example: each item must have 'code' and 'value'
        for idx, item in enumerate(items):
            if not isinstance(item, dict):
                raise TypeError(f"Item at index {idx} must be a dict for spec 3.0")
            if "code" not in item or "value" not in item:
                raise ValueError(f"Item at index {idx} missing 'code' or 'value' key for spec 3.0")
    else:
        # If spec_version is unknown, raise an error
        raise ValueError(f"Unsupported spec_version: {self.spec_version}")

    # If all checks pass, return True
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    try:
        # Normalize inventory to a mapping of version -> list of entries
        if isinstance(inventory, dict):
            entries_by_version = inventory
        elif isinstance(inventory, list):
            entries_by_version = {}
            for entry in inventory:
                if not isinstance(entry, dict):
                    continue
                v = entry.get("version")
                if v is None:
                    continue
                entries_by_version.setdefault(v, []).append(entry)
        else:
            raise TypeError("inventory must be a dict or a list of dicts")

        if version not in entries_by_version:
            raise KeyError(f"Version {version!r} not found in inventory")

        # Helper to convert a version to a sortable key
        def _sort_key(v):
            try:
                return float(v)
            except Exception:
                return v

        sorted_versions = sorted(entries_by_version.keys(), key=_sort_key)
        # Determine later versions
        later_versions = [v for v in sorted_versions if _sort_key(v) > _sort_key(version)]

        result = {}
        # Process the target version
        for entry in entries_by_version[version]:
            if not isinstance(entry, dict):
                continue
            logical_path = entry.get("logical_path")
            content_file = entry.get("content_file")
            if logical_path is None or content_file is None:
                continue
            result.setdefault(logical_path, set()).add(content_file)

        # Include duplicates from later versions
        for lv in later_versions:
            for entry in entries_by_version[lv]:
                if not isinstance(entry, dict):
                    continue
                logical_path = entry.get("logical_path")
                content_file = entry.get("content_file")
                if logical_path is None or content_file is None:
                    continue
                if logical_path in result:
                    result[logical_path].add(content_file)

        return result
    except Exception as exc:
        raise RuntimeError(f"Failed to generate logical path map: {exc}") from exc

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    if not isinstance(path, (str, bytes, os.PathLike)):
        raise TypeError("path must be a string, bytes, or PathLike object")
    try:
        if not os.path.exists(path):
            raise FileNotFoundError(f"Path does not exist: {path}")
        if not os.path.isdir(path):
            raise NotADirectoryError(f"Path is not a directory: {path}")
        entries = os.listdir(path)
        files = [entry for entry in entries if os.path.isfile(os.path.join(path, entry))]
        return files
    except OSError:
        # Return an empty list for any OS-related error (e.g., permission denied)
        return []

def add_asset(self, basename, file_path):
    """
    Adds asset(s) to the internal mapping. If `file_path` is a directory,
    all files that start with `basename` followed by a dot and an extension
    are added. If `file_path` is a file, it is added directly.
    """
    # Basic type checks
    if not isinstance(basename, str):
        raise TypeError(f"basename must be a string, got {type(basename).__name__}")
    if not isinstance(file_path, str):
        raise TypeError(f"file_path must be a string, got {type(file_path).__name__}")

    # Import os lazily to avoid top‑level imports
    try:
        import os
    except Exception as exc:
        raise RuntimeError("Failed to import os module") from exc

    # Ensure the assets dictionary exists
    if not hasattr(self, "assets") or not isinstance(self.assets, dict):
        self.assets = {}

    # Resolve absolute path
    abs_path = os.path.abspath(file_path)

    if not os.path.exists(abs_path):
        raise FileNotFoundError(f"Path does not exist: {abs_path}")

    if os.path.isdir(abs_path):
        # Add all matching files in the directory
        for entry in os.listdir(abs_path):
            entry_path = os.path.join(abs_path, entry)
            if os.path.isfile(entry_path) and entry.startswith(f"{basename}."):
                self.assets[entry] = entry_path
    else:
        # Single file case
        if os.path.basename(abs_path).startswith(f"{basename}."):
            self.assets[os.path.basename(abs_path)] = abs_path
        else:
            # If the file does not match the basename pattern, still add it
            self.assets[os.path.basename(abs_path)] = abs_path
    return None

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
        Mapping from XML basename to a dictionary of file paths and their binary contents.
    """
    import os
    import zipfile

    if not isinstance(zip_path, str):
        raise TypeError("zip_path must be a string representing the file path")

    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"Zip file not found: {zip_path}")

    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # List all non-directory entries
            all_entries = [name for name in zf.namelist() if not name.endswith('/')]

            # Identify basenames from XML files
            xml_basenames = set()
            for entry in all_entries:
                if entry.lower().endswith('.xml'):
                    basename = os.path.splitext(os.path.basename(entry))[0]
                    xml_basenames.add(basename)

            # If no XML files, return empty dict
            if not xml_basenames:
                return {}

            # Build package mapping
            packages = {basename: {} for basename in xml_basenames}
            for entry in all_entries:
                # Determine the basename of the current entry
                entry_basename = os.path.splitext(os.path.basename(entry))[0]
                if entry_basename in xml_basenames:
                    try:
                        data = zf.read(entry)
                    except RuntimeError as e:
                        # Skip files that cannot be read
                        continue
                    packages[entry_basename][entry] = data

            return packages

    except zipfile.BadZipFile as e:
        raise ValueError(f"Invalid zip file: {zip_path}") from e
    except Exception as e:
        # Re-raise any other exception with context
        raise RuntimeError(f"Error processing zip file '{zip_path}': {e}") from e

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    try:
        return content.replace('w:st="', 'w-st="')
    except Exception as exc:
        raise RuntimeError("Failed to replace namespace prefix") from exc

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    # Validate inputs
    if node is None or not isinstance(pubdate_xpaths, (list, tuple)):
        return None

    for xpath in pubdate_xpaths:
        try:
            # Execute the XPath expression
            result = node.xpath(xpath)
            if result:
                first = result[0]
                # If the result is a string, return it directly
                if isinstance(first, str):
                    return first
                # If the result is an element, return its text content
                if hasattr(first, "text"):
                    return first.text
        except Exception:
            # Ignore any errors and continue with the next XPath
            continue

    # No match found
    return None

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Helper predicates for expression types
    def is_and(expr):
        return getattr(expr, 'operator', None) == '&' or getattr(expr, 'is_and', False)

    def is_or(expr):
        return getattr(expr, 'operator', None) == '|' or getattr(expr, 'is_or', False)

    def is_not(expr):
        return getattr(expr

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    # Validate that the hook is hashable
    try:
        hash(hook)
    except TypeError:
        raise TypeError("Hook must be hashable") from None

    # Ensure the registry exists and is a dictionary
    if not hasattr(self, "registry"):
        self.registry = {}
    if not isinstance(self.registry, dict):
        raise RuntimeError("Registry must be a dictionary")

    # Ensure a list exists for this hook
    if hook not in self.registry:
        self.registry[hook] = []
    elif not isinstance(self.registry[hook], list):
        raise RuntimeError(f"Registry entry for hook {hook!r} must be a list")

    def decorator(func):
        if not callable(func):
            raise TypeError("Listener must be callable")
        try:
            if func not in self.registry[hook]:
                self.registry[hook].append(func)
        except Exception as exc:
            raise RuntimeError(f"Failed to register handler for hook {hook!r}") from exc
        return func

    return decorator

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    if not callable(namefunc):
        raise TypeError("namefunc must be callable")
    def wrapper(*args, **kwargs):
        try:
            result = namefunc(*args, **kwargs)
        except Exception:
            # propagate the original exception
            raise
        # In Python 2, convert unicode to bytestring
        if sys.version_info[0] < 3:
            try:
                unicode_type = unicode  # noqa: F821
            except NameError:
                unicode_type = str
            if isinstance(result, unicode_type):
                try:
                    return result.encode('utf-8')
                except Exception:
                    # If encoding fails, return the original result
                    return result
        return result
    return wrapper

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        # Try to import the metadata module for the current package
        try:
            from importlib.metadata import version, PackageNotFoundError
        except ImportError:
            # Fallback to the backport for older Python versions
            from importlib_metadata import version, PackageNotFoundError

        # Attempt to get the package name from the current module's package
        pkg_name = __package__
        if not pkg_name:
            # If __package__ is empty or None, raise to trigger fallback
            raise PackageNotFoundError

        # Retrieve the version of the package
        ver = version(pkg_name)
        return {"version": ver}
    except Exception:
        # If any error occurs, try to get a version from an environment variable
        import os
        env_ver = os.getenv("APP_VERSION")
        if env_ver:
            return {"version": env_ver}
        # As a last resort, return a default version string
        return {"version": "0.0.0"}

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate inputs
    if not isinstance(pieces, (list, tuple)):
        raise ValueError("pieces must be a list or tuple")
    if not isinstance(style, str):
        raise ValueError("style must be a string")

    # Extract components with defaults
    try:
        major = str(pieces[0]) if len(pieces) > 0 else "0"
        minor = str(pieces[1]) if len(pieces) > 1 else "0"
        patch = str(pieces[2]) if len(pieces) > 2 else "0"
        pre = str(pieces[3]) if len(pieces) > 3 else None
        build = str(pieces[4]) if len(pieces) > 4 else None
    except Exception as exc:
        raise ValueError(f"Error extracting version components: {exc}") from exc

    # Helper to join components
    def join_parts(parts):
        return ".".join(parts)

    # Build the version string based on style
    if style.lower() == "semver":
        base = f"{major}.{minor}.{patch}"
        if pre:
            base += f"-{pre}"
        if build:
            base += f"+{build}"
        return base
    elif style.lower() == "pep440":
        base = f"{major}.{minor}.{patch}"
        if pre:
            # PEP 440 uses a dot before pre-release
            base += f".{pre}"
        if build:
            base += f"+{build}"
        return base
    elif style.lower() == "short":
        return f"{major}.{minor}.{patch}"
    elif style.lower() == "full":
        # Same as semver but include all components even if empty
        base = f"{major}.{minor}.{patch}"
        if pre is not None:
            base += f"-{pre}"
        if build is not None:
            base += f"+{build}"
        return base
    else:
        raise ValueError(f"Unsupported style: {style}")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if pieces is None:
        raise TypeError("pieces cannot be None")
    try:
        if '+' in pieces:
            return '.'
        else:
            return '+'
    except Exception as e:
        raise TypeError("pieces must be an iterable") from e

