def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate input types
    if not isinstance(validate_objects, bool):
        raise TypeError("validate_objects must be a boolean")
    if not isinstance(check_digests, bool):
        raise TypeError("check_digests must be a boolean")
    if not isinstance(show_warnings, bool):
        raise TypeError("show_warnings must be a boolean")

    # Ensure the storage root exists and is iterable
    if not hasattr(self, "storage_root"):
        raise AttributeError("The object has no 'storage_root' attribute")
    root = self.storage_root
    try:
        iterator = iter(root)
    except TypeError:
        raise ValueError("storage_root must be an iterable")

    num_objects = 0
    good_objects = 0

    for obj in iterator:
        num_objects += 1
        is_good = True
        try:
            if validate_objects:
                # Assume the object has an is_valid() method
                if hasattr(obj, "is_valid"):
                    if not obj.is_valid():
                        is_good = False
                        if show_warnings:
                            print(f"Warning: Object {obj} failed validation.")
                else:
                    # If no validation method, skip validation
                    pass

            if check_digests:
                # Assume the object has a check_digest() method
                if hasattr(obj, "check_digest"):
                    if not obj.check_digest():
                        is_good = False
                        if show_warnings:
                            print(f"Warning: Object {obj} failed digest check.")
                else:
                    # If no digest method, skip digest check
                    pass
        except Exception as e:
            is_good = False
            if show_warnings:
                print(f"Warning: Exception while validating object {obj}: {e}")

        if is_good:
            good_objects += 1

    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    version = version.strip()
    if not version:
        raise ValueError("empty version string")
    parts = version.split('.')
    if len(parts) == 0:
        raise ValueError("invalid version format")
    # Validate each part is numeric
    for part in parts:
        if not part.isdigit():
            raise ValueError(f"non-numeric part in version: '{part}'")
    # Increment the last numeric component
    last = parts[-1]
    width = len(last)
    try:
        new_num = int(last) + 1
    except Exception as e:
        raise ValueError(f"cannot increment version part '{last}': {e}") from e
    new_part = str(new_num)
    if len(new_part) < width:
        new_part = new_part.rjust(width, '0')
    parts[-1] = new_part
    return '.'.join(parts)

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        # Basic input validation
        if not isinstance(version_dirs, list):
            raise TypeError("version_dirs must be a list of directory names")
        for v in version_dirs:
            if not isinstance(v, str):
                raise TypeError(f"Each entry in version_dirs must be a string, got {type(v).__name__}")

        # Load the root inventory once
        root_inventory_path = os.path.join(self.root_dir, "inventory.json")
        if not os.path.isfile(root_inventory_path):
            raise FileNotFoundError(f"Root inventory not found at {root_inventory_path}")
        try:
            with open(root_inventory_path, "r", encoding="utf-8") as f:
                root_inventory = json.load(f)
        except Exception as exc:
            raise RuntimeError(f"Failed to load root inventory: {exc}") from exc

        root_digests = root_inventory.get("digests", {})
        if not isinstance(root_digests, dict):
            raise ValueError("Root inventory 'digests' field must be a dictionary")

        # Prepare structures for results and error reporting
        differences = {}          # {version_dir: [(path, root_digest, version_digest), ...]}
        missing_inventories = []  # list of version dirs missing an inventory file
        load_errors = []          # list of tuples (version_dir, error_message)

        # Iterate over each version directory in order
        for vdir in version_dirs:
            inv_path = os.path.join(vdir, "inventory.json")
            if not os.path.isfile(inv_path):
                missing_inventories.append(vdir)
                continue

            try:
                with open(inv_path, "r", encoding="utf-8") as f:
                    inv = json.load(f)
            except Exception as exc:
                load_errors.append((vdir, str(exc)))
                continue

            inv_digests = inv.get("digests", {})
            if not isinstance(inv_digests, dict):
                load_errors.append((vdir, "Inventory 'digests' field is not a dictionary"))
                continue

            # Compare digests with the root inventory
            diff = []
            for path, ver_digest in inv_digests.items():
                root_digest = root_digests.get(path)
                if root_digest is None:
                    # Path missing in root inventory
                    diff.append((path, None, ver_digest))
                elif root_digest != ver_digest:
                    diff.append((path, root_digest, ver_digest))

            if diff:
                differences[vdir] = diff

        # Raise informative errors if any issues were detected
        if missing_inventories:
            raise FileNotFoundError(
                f"Missing inventory files for the following versions: {', '.join(missing_inventories)}"
            )
        if load_errors:
            messages = "; ".join([f"{vdir}: {msg}" for vdir, msg in load_errors])
            raise RuntimeError(f"Errors loading inventories: {messages}")

        # Return a mapping of version directories to their differing digests
        return differences

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to merge two lists of mapping node tuples
    def _merge_mapping_lists(list1, list2):
        merged = {}
        for k_node, v_node in list1:
            key = k_node.value
            merged[key] = (k_node, v_node)
        for k_node, v_node in list2:
            key = k_node.value
            if key in merged:
                existing_k, existing_v = merged[key]
                if isinstance(existing_v, MappingNode) and isinstance(v_node, MappingNode):
                    merged_value = _merge_mapping_lists(existing_v.value, v_node.value)
                    merged[key] = (existing_k, MappingNode(tag=existing_v.tag, value=merged_value))
                else:
                    merged[key] = (existing_k, v_node)
            else:
                merged[key] = (k_node, v_node)
        return list(merged.values())

    if not isinstance(nodes, list):
        raise ValueError('nodes must be a list of tuples')
    merged = {}
    for item in nodes:
        if not isinstance(item, tuple) or len(item) != 2:
            raise ValueError('each item must be a tuple of (ScalarNode, Node)')
        key_node, value_node = item
        if not hasattr(key_node, 'value'):
            raise ValueError('key must be a ScalarNode with a value attribute')
        key = key_node.value
        if key in merged:
            existing_k, existing_v = merged[key]
            if isinstance(existing_v, MappingNode) and isinstance(value_node, MappingNode):
                merged_value = _merge_mapping_lists(existing_v.value, value_node.value)
                merged[key] = (existing_k, MappingNode(tag=existing_v.tag, value=merged_value))
            else:
                merged[key] = (existing_k, value_node)
        else:
            merged[key] = (key_node, value_node)
    return list(merged.values())

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    try:
        actions = getattr(parser, '_actions', [])
    except Exception:
        return ''
    flags = []
    for action in actions:
        try:
            option_strings = getattr(action, 'option_strings', [])
            if option_strings:
                flags.extend(option_strings)
        except Exception:
            continue
    return ' '.join(flags)

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Basic type validation
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError("unparsed_arguments must be a list or tuple of strings")
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dictionary mapping names to ArgumentParser instances")
    for name, parser in subparsers.items():
        if not isinstance(name, str):
            raise TypeError(f"Subparser name {name!r} is not a string")
        if not hasattr(parser, 'parse_known_args'):
            raise TypeError(f"Subparser {name!r} does not have a parse_known_args method")

    parsed_results = {}
    claimed_counts = {}  # counts of arguments claimed by any subparser

    for name, parser in subparsers.items():
        try:
            namespace, remaining = parser.parse_known_args(unparsed_arguments)
        except Exception as exc:
            raise RuntimeError(f"Error parsing arguments for subparser '{name}': {exc}") from exc

        parsed_results[name] = namespace

        # Count remaining arguments
        remaining_counts = {}
        for arg in remaining:
            remaining_counts[arg] = remaining_counts.get(arg, 0) + 1

        # Determine consumed arguments for this subparser
        consumed = []
        for arg in unparsed_arguments:
            if remaining_counts.get(arg, 0) > 0:
                remaining_counts[arg] -= 1
            else:
                consumed.append(arg)

        # Update global claimed counts
        for arg in consumed:
            claimed_counts[arg] = claimed_counts.get(arg, 0) + 1

    # Compute final remaining arguments not claimed by any subparser
    final_remaining = []
    for arg in unparsed_arguments:
        if claimed_counts.get(arg, 0) > 0:
            claimed_counts[arg] -= 1
        else:
            final_remaining

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to determine if a node is a MappingNode
    def is_mapping_node(node):
        try:
            # MappingNode.value is a list of (key, value) tuples
            return isinstance(node.value, list) and all(
                isinstance(pair, tuple) and len(pair) == 2 for pair in node.value
            )
        except AttributeError:
            return False

    # Recursive merge of two mapping nodes
    def merge_mapping_nodes(a, b):
        if not is_mapping_node(a) or not is_mapping_node(b):
            # If either is not a mapping, the last wins
            return b
        # Build dict from a's mapping for quick lookup
        a_dict = {key_node.value: (key_node, val_node) for key_node, val_node in a.value}
        # Merge entries from b
        for key_node_b, val_node_b in b.value:
            key = key_node_b.value
            if key in a_dict:
                key_node_a, val_node_a = a_dict[key]
                # Merge values recursively
                merged_val = merge_mapping_nodes(val_node_a, val_node_b)
                a_dict[key] = (key_node_a, merged_val)
            else:
                a_dict[key] = (key_node_b, val_node_b)
        # Preserve order: keys from a first, then new keys from b
        merged_list = []
        seen = set()
        for key_node, val_node in a.value:
            key = key_node.value
            if key in a_dict:
                merged_list.append(a_dict[key])
                seen.add(key)
        for key_node, val_node in b.value:
            key = key_node.value
            if key not in seen:
                merged_list.append(a_dict[key])
        return type(a)(tag=a.tag, value=merged_list)

    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list')
    result_dict = {}
    order = []
    for item in nodes:
        if not isinstance(item, tuple) or len(item) != 2:
            raise ValueError('each node must be a tuple of (ScalarNode, value)')
        key_node, val_node = item
        if not hasattr(key_node, 'value'):
            raise ValueError('key node must have a value attribute')
        key = key_node.value
        if key in result_dict:
            existing_val = result_dict[key]
            merged_val = merge_mapping_nodes(existing_val, val_node)
            result_dict[key] = merged_val
        else:
            result_dict[key] = val_node
            order.append(key)
    # Build result list preserving order
    result = [(key_node, result_dict[key]) for key_node, key in zip(
        [k for k in nodes if k[0].value in order], order)]
    # The above zip may not preserve original key nodes if duplicates; reconstruct properly
    # Instead, iterate over original nodes and pick first occurrence
    seen = set()
    final = []
    for key_node, val_node in nodes:
        key = key_node.value
        if key not in seen:
            final.append((key_node, result_dict[key]))
            seen.add(key)
    return final

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Basic input validation
    if unparsed_arguments is None:
        unparsed_arguments = []
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError("unparsed_arguments must be a list or tuple of strings")
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dictionary mapping names to ArgumentParser instances")

    parsed_results = {}
    claimed_set = set()

    for name, parser in subparsers.items():
        if not hasattr(parser, 'parse_known_args'):
            raise TypeError(f"Subparser for '{name}' does not appear to be an ArgumentParser")
        try:
            namespace, remaining = parser.parse_known_args(unparsed_arguments)
        except SystemExit as exc:
            # argparse uses SystemExit on parse errors; convert to ValueError
            raise ValueError(f"Error parsing arguments for subparser '{name}': {exc}") from exc
        parsed_results[name] = namespace
        # Determine which arguments were claimed by this parser
        claimed = set(unparsed_arguments) - set(remaining)
        claimed_set.update(claimed)

    # Remaining arguments not claimed by any subparser
    remaining_args = [arg for arg in unparsed_arguments if arg not in claimed_set]

    return parsed_results, remaining_args

def make_parsers():
    '''
    Build a top-level parser and its subparsers and return them as a tuple.
    '''
    try:
        parser = argparse.ArgumentParser(description='Top-level command parser')
        subparsers = parser.add_subparsers(dest='command', required=True)
        return parser, subparsers
    except Exception as exc:
        raise RuntimeError('Failed to create parsers') from exc

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate input types
    if response is None or not isinstance(response, list):
        raise TypeError("response must be a list")
    if not isinstance(max_results, int):
        raise TypeError("max_results must be an integer")
    if max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    try:
        for start in range(0, len(response), max_results):
            yield response[start:start + max_results]
    except Exception as exc:
        raise RuntimeError(f"Error while paging response: {exc}") from exc

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError("Input cannot be None")
    try:
        iterator = iter(dicts)
    except TypeError:
        raise TypeError("Input must be an iterable of dictionaries")

    result = {}
    for d in iterator:
        if not isinstance(d, dict):
            raise TypeError(f"Expected a dict, got {type(d).__name__}")
        for key, value in d.items():
            if key in result:
                try:
                    result[key] += value
                except TypeError:
                    raise TypeError(f"Cannot sum values for key '{key}': incompatible types")
            else:
                result[key] = value
    return result

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    try:
        if not isinstance(val, str):
            return False
        return val.strip().lower() == "none"
    except Exception:
        return False

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Validate input
    if parser is None:
        raise TypeError("parser cannot be None")
    if not hasattr(parser, "_actions"):
        raise TypeError("parser must be an argparse.ArgumentParser instance")

    flags = []
    for action in parser._actions:
        # action.option_strings is a list of flag strings (e.g., ['-f', '--foo'])
        option_strings = getattr(action, "option_strings", None)
        if option_strings:
            flags.extend(option_strings)

    return " ".join(flags)

def _replace_register(flow_params, register_number, register_value):
    """
    Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    :return: The modified flow_params dictionary
    """
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")

    def _traverse(obj):
        if isinstance(obj, dict):
            for key, value in list(obj.items()):
                if key == register_value:
                    obj[key] = register_number
                _traverse(value)
        elif isinstance(obj, (list, tuple, set)):
            for item in obj:
                _traverse(item)

    _traverse(flow_params)
    return flow_params

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError("value must be a string")
    if not isinstance(arg, str):
        raise TypeError("arg must be a string")
    try:
        return value.replace('.', arg)
    except Exception as exc:
        raise RuntimeError(f"Failed to replace dots: {exc}") from exc

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class, got {type(cls).__name__}")
    result = set()
    stack = [cls]
    while stack:
        current = stack.pop()
        try:
            subs = current.__subclasses__()
        except Exception:
            continue
        for sub in subs:
            if sub not in result:
                result.add(sub)
                stack.append(sub)
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate alphabet
    if not alphabet:
        raise ValueError("Alphabet must contain at least one character.")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet contains duplicate characters.")
    base = len(alphabet)

    # Build a mapping from character to its numeric value
    char_to_value = {ch: idx for idx, ch in enumerate(alphabet)}

    # Validate string
    if string == "":
        raise ValueError("Input string must not be empty.")

    result = 0
    for ch in string:
        if ch not in char_to_value:
            raise ValueError(f"Character '{ch}' not found in alphabet.")
        result = result * base + char_to_value[ch]

    return result

def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    # Validate inputs
    if not isinstance(url, str) or not url:
        raise TypeError("url must be a non-empty string")
    if not isinstance(destination_path, Path):
        raise TypeError("destination_path must be a pathlib.Path instance")

    # Ensure destination directory exists
    try:
        destination_path.mkdir(parents=True, exist_ok=True)
    except Exception as exc:
        raise RuntimeError(f"Could not create destination directory '{destination_path}': {exc}") from exc

    # Download the archive
    try:
        response = requests.get(url, stream=True, timeout=30)
        response.raise_for_status()
    except Exception as exc:
        raise RuntimeError(f"Failed to download archive from '{url}': {exc}") from exc

    # Write to a temporary file
    temp_file = destination_path / "temp_repo_archive.tar.gz"
    try:
        with open(temp_file, "wb") as f:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    f.write(chunk)
    except Exception as exc:
        raise RuntimeError(f"Failed to write archive to disk: {exc}") from exc

    # Extract the archive
    extracted_root = destination_path
    try:
        import tarfile
        with tarfile.open(temp_file, "r:gz") as tar:
            tar.extractall(path=destination_path)
            # Determine the top-level directory inside the archive
            root_dirs = set()
            for member in tar.getmembers():
                parts = Path(member.name).parts
                if parts:
                    root_dirs.add(parts[0])
            if len(root_dirs) == 1:
                extracted_root = destination_path / next(iter(root_dirs))
    except Exception as exc:
        raise RuntimeError(f"Failed to extract archive: {exc}") from exc
    finally:
        # Clean up temporary file
        try:
            temp_file.unlink()
        except Exception:
            pass

    return extracted_root

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    # Strip leading and trailing single or double quotes
    return name.strip('\'"')

def addignored(ignored):
    '''Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    # Validate the input type
    if not isinstance(ignored, (list, str)):
        raise TypeError("ignored must be a list or a string")
    try:
        # Run git to list ignored files
        output = subprocess.check_output(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            text=True,
            stderr=subprocess.DEVNULL
        )
    except (subprocess.CalledProcessError, OSError):
        # If git command fails or git is not available, return an empty string
        return ''
    # Convert output to a sorted list of file names
    files = [line.strip() for line in output.splitlines() if line.strip()]
    files.sort()
    # Return as a comma‑separated string
    return ','.join(files)

def match(filename):
    """
    Check if the filename is a type that this module supports

    Args:
        filename: Filename to match
    Returns:
        False if not a match, True if supported
    """
    try:
        if not isinstance(filename, str):
            return False
        _, ext = os.path.splitext(filename)
        return ext.lower() in {'.txt', '.md', '.py', '.json', '.yaml', '.yml'}
    except Exception:
        return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not isinstance(host, str) or not host:
        return False
    try:
        # Direct string checks
        if host == "localhost":
            return True
        # Check if host is an IPv4 address
        try:
            if socket.inet_aton(host) == socket.inet_aton("127.0.0.1"):
                return True
        except OSError:
            pass
        # Check if host is an IPv6 address
        try:
            if socket.inet_pton(socket.AF_INET6, host) == socket.inet_pton(socket.AF_INET6, "::1"):
                return True
        except (OSError, AttributeError):
            pass

        # Resolve the host and inspect the addresses
        for res in socket.getaddrinfo(host, None):
            family, _, _, _, sockaddr = res
            if family == socket.AF_INET:
                ip = sockaddr[0]
                if ip.startswith("127."):
                    return True
            elif family == socket.AF_INET6:
                ip = sockaddr[0]
                if ip in ("::1", "0:0:0:0:0:0:0:1"):
                    return True
        return False
    except Exception:
        return False

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # On Windows, Git Bash sets the MSYSTEM environment variable
        if os.name == 'nt':
            return 'MSYSTEM' in os.environ

        # On POSIX-like environments (MSYS/Cygwin), OSTYPE contains 'msys' or 'cygwin'
        ostype = os.environ.get('OSTYPE', '').lower()
        if 'msys' in ostype or 'cygwin' in ostype:
            return True

        # Additional check for MSYSTEM on POSIX
        if 'MSYSTEM' in os.environ:
            return True

        return False
    except Exception:
        # In case of any unexpected error, default to False
        return False

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Determine the variable name and optional default from the matcher
    if isinstance(matcher, (list, tuple)):
        if not matcher:
            raise TypeError("Matcher must contain at least a variable name.")
        name = matcher[0]
        default = matcher[1] if len(matcher) > 1 else None
    elif isinstance(matcher, str):
        name = matcher
        default = None
    else:
        raise TypeError("Matcher must be a string or a tuple/list containing the variable name and optional default.")

    if not isinstance(name, str):
        raise TypeError("Variable name must be a string.")

    # Retrieve the environment variable
    value = os.getenv(name)

    # If not found, use default if provided, otherwise raise an error
    if value is None:
        if default is not None:
            return default
        raise KeyError(f"Environment variable '{name}' not found and no default provided.")

    return value

def is_ipv4(target):
    """ Test if IPv4 address or not
    """
    try:
        addr = ipaddress.ip_address(target)
        return isinstance(addr, ipaddress.IPv4Address)
    except (ValueError, TypeError):
        return False

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        # Validate dumper argument
        if dumper is not None:
            if not isinstance(dumper, type) or not issubclass(dumper, yaml.Dumper):
                raise TypeError("dumper must be a yaml.Dumper subclass or None")
        # Prepare keyword arguments for yaml.dump
        dump_kwargs = {}
        if dumper is not None:
            dump_kwargs["Dumper"] = dumper
        # Perform the dump
        result = yaml.dump(obj, **dump_kwargs)
        # Ensure the result is a string (unicode in Py2, str in Py3)
        if not isinstance(result, str):
            result = str(result)
        return result
    except yaml.YAMLError as exc:
        raise ValueError(f"Failed to dump object to YAML string: {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Unexpected error during YAML dump: {exc}") from exc

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    if x is None:
        raise ValueError("Input cannot be None.")
    try:
        x_arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise TypeError("Input must be a numeric scalar or array-like.") from e
    sigma = 0.1
    center = 0.2
    try:
        result = np.exp(-((x_arr - center)**2) / (2 * sigma**2))
    except Exception as e:
        raise RuntimeError("Error computing Gaussian.") from e
    return result

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8. If ``obj`` is not a string,
    it is returned unchanged.
    """
    if isinstance(obj, str):
        try:
            return obj.encode("utf-8")
        except UnicodeEncodeError as exc:
            raise ValueError(f"Unable to encode string to UTF-8: {exc}") from exc
    return obj

@classmethod
    def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        if values is None:
            raise ValueError("values cannot be None")
        try:
            iterator = iter(values)
        except TypeError:
            raise TypeError("values must be an iterable of strings")
        bookmarks = cls()
        for raw in iterator:
            if not isinstance(raw, str):
                continue
            try:
                bookmark = Bookmark.from_raw_value(raw)
            except Exception:
                continue
            try:
                bookmarks.add(bookmark)
            except Exception:
                continue
        return bookmarks

def scale(self, other=None, recompute=False):
    """
    Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before, it is computed and stored for
    subsequent use (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram one must explicitly
    recompute the scale if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Helper to compute the integral of the histogram
    def _compute_scale():
        try:
            # Support list/tuple or numpy array
            if isinstance(self._bins, (list, tuple)):
                return sum(self._bins)
            else:
                return float(self._bins.sum())
        except Exception as exc:
            raise ValueError("Failed to compute histogram scale") from exc

    # If no new scale is requested, return the current scale
    if other is None:
        if self._scale is None or recompute:
            self._scale = _compute_scale()
        return self._scale

    # Rescaling requested
    if not isinstance(other, (int, float)):
        raise TypeError("other must be a float or int")

    # Ensure current scale is known
    if self._scale is None:
        self._scale = _compute_scale()

    if self._scale == 0:
        raise LenaValueError("Cannot rescale histogram with zero scale")

    factor = other / self._scale

    # Scale the bin contents in place
    if isinstance(self._bins, (list, tuple)):
        for i in range(len(self._bins)):
            self._bins[i] *= factor
    else:
        # Assume numpy array or similar
        self._bins *= factor

    self._scale = other
    return None

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Getter
    if other is None:
        return self.scale

    # Validate new scale
    try:
        new_scale = float(other)
    except Exception as exc:
        raise TypeError("Scale must be a numeric value") from exc

    if new_scale == 0:
        raise ValueError("Scale cannot be zero")

    # Current scale must be known and non‑zero
    if getattr(self, "scale", None) in (None, 0):
        raise LenaValueError("Cannot rescale graph with unknown or zero scale")

    factor = new_scale / self.scale

    # Rescale the last coordinate field
    fields = getattr(self, "fields", None)
    if not fields:
        raise AttributeError("Graph has no fields to rescale")
    last_field = fields[-1]
    try:
        # Try in‑place multiplication
        last_field *= factor
    except Exception:
        # Fallback: try a 'data' attribute
        if hasattr(last_field, "data"):
            last_field.data *= factor
        else:
            raise

    # Rescale all errors
    errors = getattr(self, "errors", None)
    if errors:
        for err in errors:
            try:
                err *= factor
            except Exception:
                if hasattr(err, "data"):
                    err.data *= factor
                else:
                    # If we cannot rescale this error, ignore it
                    pass

    # Update the graph's scale
    self.scale = new_scale
    return None

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    else:
        del self[key]
        return value

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    try:
        # Ensure required attributes exist
        if not hasattr(self, 'key_map') or not hasattr(self, 'freq_map') or not hasattr(self, 'min_freq'):
            raise AttributeError('LFU cache missing required attributes')
        # If cache is empty, raise KeyError
        if not self.key_map:
            raise KeyError('Cache is empty')
        # Determine the current minimum frequency
        min_freq = self.min_freq
        freq_dict = self.freq_map.get(min_freq)
        # If the min_freq bucket is missing or empty, find the next one
        if not freq_dict:
            if not self.freq_map:
                raise KeyError('Cache is empty')
            min_freq = min(self.freq_map.keys())
            freq_dict = self.freq_map[min_freq]
        # Pop the least recently used key within the min_freq bucket
        key = next(iter(freq_dict))
        freq_dict.pop(key)
        # If the bucket is now empty, remove it and update min_freq
        if not freq_dict:
            del self.freq_map[min_freq]
            if self.freq_map:
                self.min_freq = min(self.freq_map.keys())
            else:
                self.min_freq = 0
        # Retrieve the value and frequency from key_map
        value, freq = self.key_map.pop(key)
        return (key, value)
    except Exception as exc:
        raise RuntimeError(f'Error in popitem: {exc}') from exc

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        # Attempt to locate the underlying storage attribute
        container = getattr(self, "_cache", None)
        if container is None:
            container = getattr(self, "_data", None)
        if container is None:
            container = getattr(self, "data", None)
        if container is None:
            raise AttributeError("No suitable container attribute found.")
        # Try to pop the most recently used item
        if hasattr(container, "popitem"):
            try:
                return container.popitem(last=True)
            except TypeError:
                # Fallback for plain dicts that don't accept the 'last' argument
                return container.popitem()
        else:
            raise AttributeError("Underlying container does not support popitem.")
    except KeyError:
        raise KeyError("popitem(): dictionary is empty")
    except Exception as exc:
        raise RuntimeError(f"Failed to pop item: {exc}") from exc

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    try:
        # Ensure the object behaves like a dictionary
        if not hasattr(self, 'keys') or not hasattr(self, 'pop'):
            raise TypeError('popitem() requires a dict-like object')
        # Check if the dictionary is empty
        if not self:
            raise KeyError('popitem(): dictionary is empty')
        # Select a random key
        import random
        key = random.choice(list(self.keys()))
        # Remove and return the key-value pair
        value = self.pop(key)
        return key, value
    except KeyError:
        raise
    except Exception as exc:
        raise RuntimeError(f'Error in popitem: {exc}') from exc

def _create_converter(self) -> _converting._Converter:
    """
    Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    try:
        # Retrieve the converter class from the _converting module
        converter_cls = getattr(_converting, "_Converter")
        if not callable(converter_cls):
            raise TypeError(f"_converting._Converter is not callable: {converter_cls!r}")
        # Instantiate and return the converter
        return converter_cls()
    except Exception as exc:
        # Wrap any exception in a RuntimeError to provide a clear error message
        raise RuntimeError("Failed to create the parameter style converter") from exc

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        if request is None:
            return False

        # Check for a public message attribute
        if getattr(request, "public_message", None):
            return True

        # Check for a private message attribute
        if getattr(request, "private_message", None):
            return True

        # Check for a legacy payload indicator
        payload = getattr(request, "payload", None)
        if payload and isinstance(payload, dict):
            if payload.get("legacy"):
                return True

        # Fallback: some requests may expose a type field
        if getattr(request, "type", None) == "diaspora":
            return True

    except Exception:
        # Any unexpected error should result in a safe False
        return False

    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request.
    A request is considered a Matrix request if:
    1. Its path starts with '/_matrix'.
    2. It contains a header named 'X-Matrix-Request'.
    3. It has a JSON content type and the path contains the word 'matrix'.
    The function is tolerant to missing attributes and will return False for
    any unexpected input or runtime errors.
    """
    try:
        if request is None:
            return False

        # Check the request path
        path = getattr(request, "path", None)
        if isinstance(path, str) and path.startswith("/_matrix"):
            return True

        # Check headers (case‑insensitive)
        headers = getattr(request, "headers", {})
        if isinstance(headers, dict):
            for key, value in headers.items():
                if key.lower() == "x-matrix-request":
                    return True
                if key.lower() == "content-type" and isinstance(value, str):
                    if "application/json" in value.lower():
                        if isinstance(path, str) and "matrix" in path.lower():
                            return True

        return False
    except Exception:
        # Any unexpected error results in a conservative False
        return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    The expected format is ISO 8601 UTC with a trailing 'Z', e.g. '2023-08-15T12:34:56Z'.
    """
    if dt is None:
        raise ValueError("dt cannot be None")
    if not hasattr(dt, "strftime"):
        raise TypeError("dt must be a datetime instance")
    try:
        # If dt is timezone-aware, convert to UTC
        if getattr(dt, "tzinfo", None) is not None and dt.tzinfo.utcoffset(dt) is not None:
            try:
                # Use datetime.timezone.utc if available
                dt_utc = dt.astimezone(datetime.timezone.utc)
            except Exception:
                # Fallback: strip tzinfo and assume UTC
                dt_utc = dt.replace(tzinfo=None)
        else:
            dt_utc = dt

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    try:
        if not isinstance(tag, str):
            return False
        if not tag:
            return False
        # Optional length restriction (common in tag systems)
        if len(tag) > 30:
            return False
        import re
        # Tags must be lowercase alphanumerics, optionally separated by single hyphens or underscores
        pattern = re.compile(r'^[a-z0-9]+(?:[-_][a-z0-9]+)*$')
        return bool(pattern.fullmatch(tag))
    except Exception:
        return False

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    try:
        children = list(node)
    except Exception as exc:
        raise TypeError("node must be an XML element with iterable children") from exc

    result = {}
    for child in children:
        key = child.tag
        if key in result:
            # If we already have a value for this tag, convert to a list
            if isinstance(result[key], list):
                result[key].append(child)
            else:
                result[key] = [result[key], child]
        else:
            result[key] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Basic validation of the base URL
    if not isinstance(url, str) or not url.strip():
        raise ValueError("url must be a non-empty string")
    try:
        from urllib.parse import urlparse, urljoin
    except Exception as exc:
        raise RuntimeError("Failed to import URL parsing utilities") from exc

    parsed = urlparse(url)
    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        raise ValueError("url must be a valid HTTP/HTTPS URL")

    # Determine the NodeInfo document path
    if document_path is None:
        nodeinfo_path = "/nodeinfo/2.0"
    else:
        if not isinstance(document_path, str):
            raise ValueError("document_path must be a string")
        nodeinfo_path = document_path

    # If the supplied path is a full URL, use it directly
    if nodeinfo_path.startswith(("http://", "https://")):
        href = nodeinfo_path
    else:
        # Ensure the path starts with a slash for proper joining
        if not nodeinfo_path.startswith("/"):
            nodeinfo_path = "/" + nodeinfo_path
        href = urljoin(url.rstrip("/"), nodeinfo_path)

    # Construct the .well-known document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href,
            }
        ]
    }

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    Returns True if the signature is valid, False otherwise.
    """
    try:
        # Import required modules locally to avoid global imports
        import base64
        from cryptography.hazmat.primitives import serialization, hashes
        from cryptography.hazmat.primitives.asymmetric import padding

        # Ensure doc is a string; if not, attempt to convert
        if not isinstance(doc, str):
            try:
                doc = str(doc)
            except Exception:
                return False

        # Load the public key (PEM format expected)
        if isinstance(public_key, str):
            key_data = public_key.encode("utf-8")
        else:
            key_data = public_key
        try:
            pub_key = serialization.load_pem_public_key(key_data)
        except Exception:
            # If PEM loading fails, try loading from a file path
            try:
                with open(public_key, "rb") as f:
                    pub_key = serialization.load_pem_public_key(f.read())
            except Exception:
                return False

        # Decode the signature from base64
        try:
            sig_bytes = base64.b64decode(signature)
        except Exception:
            return False

        # Verify the signature using RSA PKCS#1 v1.5 and SHA-256
        pub_key.verify(
            sig_bytes,
            doc.encode("utf-8"),
            padding.PKCS1v15(),
            hashes.SHA256(),
        )
        return True
    except Exception:
        # Any error during verification results in a False return
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str) or not document.strip():
        raise ValueError("Input document must be a non-empty string")

    # Helper to strip namespace from tag
    def _strip_ns(tag: str) -> str:
        return tag.split('}', 1)[-1] if '}' in tag else tag

    # Try JSON first
    try:
        json = __import__('json')
        data = json.loads(document)
        if not isinstance(data, dict):
            raise ValueError("JSON webfinger must be an object")
        subject = data.get('subject')
        aliases = data.get('aliases', [])
        links = data.get('links', [])
        if not isinstance(aliases, list):
            aliases = [aliases]
        if not isinstance(links, list):
            links = [links]
        return {
            'subject': subject,
            'aliases': aliases,
            'links': links
        }
    except Exception:
        pass  # fall back to XRD

    # Try XRD (XML) parsing
    try:
        ET = __import__('xml.etree.ElementTree')
        root = ET.fromstring(document)
        subject = None
        aliases = []
        links = []

        for child in root.iter():
            tag = _strip_ns(child.tag)
            if tag == 'Subject' and subject is None:
                subject = child.text
            elif tag == 'Alias':
                if child.text:
                    aliases.append(child.text)
            elif tag == 'Link':
                link_attrs = child.attrib.copy()
                # If Link has nested elements like <Link rel="..."><Href>...</Href></Link>
                # we can also capture text content if present
                if child.text and child.text.strip():
                    link_attrs['href'] = child.text.strip()
                links.append(link_attrs)

        if subject is None:
            raise ValueError("XRD webfinger missing Subject element")
        return {
            'subject': subject,
            'aliases': aliases,
            'links': links
        }
    except Exception as e:
        raise ValueError(f"Failed to parse webfinger document: {e}") from e

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        # Basic validation of the handle
        if not isinstance(handle, str):
            return None
        handle = handle.strip()
        if '@' not in handle:
            return None
        local_part, domain = handle.split('@', 1)
        if not local_part or not domain:
            return None

        # Construct the webfinger URL
        from urllib.parse import quote
        resource = f"acct:{handle}"
        encoded_resource = quote(resource, safe='')
        url = f"https://{domain}/.well-known/webfinger?resource={encoded_resource}"

        # Perform the HTTP GET request
        from urllib.request import Request, urlopen
        from urllib.error import URLError, HTTPError

        req = Request(url, headers={'Accept': 'application/json'})
        with urlopen(req, timeout=5) as resp:
            if resp.status != 200:
                return None
            content = resp.read()
            # Decode using utf-8, fallback to latin1 if needed
            try:
                return content.decode('utf-8')
            except UnicodeDecodeError:
                return content.decode('latin1')
    except (URLError, HTTPError, ValueError, Exception):
        # Any error (network, parsing, etc.) results in None
        return None

