@classmethod
def validate_from_content(cls, spec_content=None):
    """
    Validates that spec (YAML) content has all required fields.

    :param spec_content: content of spec file (string, bytes, or dict)
    :raise IRValidatorException: when mandatory data is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    # Basic sanity check
    if spec_content is None:
        raise IRValidatorException("Spec content is None")

    # If already a dict, use it directly
    if isinstance(spec_content, dict):
        data = spec_content
    else:
        # If bytes, decode to string
        if isinstance(spec_content, (bytes, bytearray)):
            try:
                spec_content = spec_content.decode("utf-8")
            except Exception as e:
                raise IRValidatorException(f"Failed to decode spec content: {e}") from e

        # Parse YAML string
        try:
            import yaml
            data = yaml.safe_load(spec_content)
        except Exception as e:
            raise IRValidatorException(f"Failed to parse spec content: {e}") from e

    # Ensure the parsed data is a mapping
    if not isinstance(data, dict):
        raise IRValidatorException("Spec content must be a mapping (dictionary)")

    # Define required fields (adjust as needed for your spec)
    required_fields = ["name", "version", "description"]
    missing = [field for field in required_fields if field not in data or data[field] is None]
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    if not isinstance(parser_dict, dict):
        raise TypeError("parser_dict must be a dict")

    resolved_cache = {}

    def _resolve(group_name, stack):
        if group_name in resolved_cache:
            return resolved_cache[group_name]
        if group_name in stack:
            raise ValueError(
                f"Circular include detected: {' -> '.join(stack + [group_name])}"
            )
        group_dict = parser_dict.get(group_name)
        if group_dict is None:
            raise ValueError(f"Included group '{group_name}' not found")
        if not isinstance(group_dict, dict):
            raise TypeError(f"Group '{group_name}' must be a dict")

        stack.append(group_name)
        merged = {}

        includes = group_dict.get("include")
        if includes is not None:
            if not isinstance(includes, (list, tuple)):
                raise TypeError(
                    f"'include' in group '{group_name}' must be a list or tuple"
                )
            for inc in includes:
                inc_resolved = _resolve(inc, stack)
                merged.update(inc_resolved)

        # Merge the current group's own keys, overriding any included ones
        for key, value in group_dict.items():
            if key != "include":
                merged[key] = value

        stack.pop()
        resolved_cache[group_name] = merged
        return merged

    for grp in list(parser_dict.keys()):
        try:
            parser_dict[grp] = _resolve(grp, [])
        except Exception as exc:
            raise ValueError(f"Error resolving group '{grp}': {exc}") from exc
    # The method modifies parser_dict in place and returns None.

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    try:
        spec = getattr(self, 'spec', None)
        if not isinstance(spec, dict):
            raise TypeError("spec attribute must be a dict")
        args = getattr(self, 'args', {})
        if not isinstance(args, dict):
            args = {}
        resolved = {}
        for key, spec_item in spec.items():
            if not isinstance(spec_item, dict):
                continue
            if key in args:
                resolved[key] = args[key]
                continue
            if 'default' in spec_item:
                resolved[key] = spec_item['default']
            else:
                resolved[key] = None
        return resolved
    except Exception:
        # Return an empty dict on any unexpected error
        return {}

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    # Attempt to retrieve the internal mapping of deprecated arguments.
    # If the attribute is missing or not a dictionary, return an empty dict.
    deprecated = getattr(self, "_deprecated_args", {})
    if not isinstance(deprecated, dict):
        return {}
    # Return a shallow copy to prevent accidental external mutation.
    return dict(deprecated)

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    try:
        if not isinstance(cli_args, dict):
            raise TypeError("cli_args must be a dictionary")
        if not isinstance(answer_file_args, dict):
            raise TypeError("answer_file_args must be a dictionary")

        # List of deprecated arguments; can be overridden by subclass attribute
        deprecated = getattr(self, "deprecated_args", None)
        if deprecated is None:
            # Default deprecated arguments
            deprecated = ["old_flag", "legacy_option", "deprecated_mode"]

        for arg in deprecated:
            if arg in cli_args:
                print(f"Warning: Argument '{arg}' is deprecated and will be ignored.")
            if arg in answer_file_args:
                print(f"Warning: Argument '{arg}' in answer file is deprecated and will be ignored.")
    except Exception as exc:
        print(f"Error validating deprecated arguments: {exc}")

def get_parser_option_specs(self, command_name):
    """
    Gets all the options for the specified command.

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input
    if not isinstance(command_name, str) or not command_name.strip():
        raise ValueError("command_name must be a non-empty string")

    try:
        # Attempt to retrieve the command options mapping
        options_map = getattr(self, "_command_options", None)
        if options_map is None:
            raise AttributeError("The object does not contain a '_command_options' attribute")

        # Ensure the command exists in the mapping
        if command_name not in options_map:
            raise KeyError(f"Command '{command_name}' not found in parser options")

        command_options = options_map[command_name]

        # Normalise the result to a list
        if isinstance(command_options, dict):
            # Return the keys of the dict as the option names
            return list(command_options.keys())
        try:
            # If it's already iterable (list, tuple, set, etc.)
            return list(command_options)
        except TypeError:
            # Fallback: wrap the single value in a list
            return [command_options]

    except Exception as exc:
        # Wrap any unexpected exception in a RuntimeError for clarity
        raise RuntimeError(f"Failed to retrieve parser options for '{command_name}': {exc}") from exc

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    # Validate input types
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not isinstance(argument_name, str):
        raise TypeError("argument_name must be a string")

    try:
        # Retrieve the command object
        command = self.commands.get(command_name)
        if command is None:
            raise KeyError(f"Command '{command_name}' not found")

        # Get the options mapping from the command
        options = getattr(command, "options", {})
        if not isinstance(options, dict):
            options = {}

        # Retrieve the option specification
        spec = options.get(argument_name)
        if spec is None:
            raise KeyError(f"Option '{argument_name}' not found in command '{command_name}'")

        return spec

    except (KeyError, TypeError) as exc:
        # Re‑raise known errors unchanged
        raise exc
    except Exception as exc:
        # Wrap unexpected errors in a RuntimeError for clarity
        raise RuntimeError(
            f"Failed to retrieve option spec for command '{command_name}', "
            f"argument '{argument_name}': {exc}"
        ) from exc

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    try:
        # If no arguments provided, return empty list
        if args is None:
            return []

        # Handle dictionary input: keys that start with '_' or have None/empty values
        if isinstance(args, dict):
            return [
                key
                for key, value in args.items()
                if (
                    (isinstance(key, str) and key.startswith("_"))
                    or value is None
                    or value == ""
                )
            ]

        # Handle iterable inputs (list, tuple, set)
        if isinstance(args, (list, tuple, set)):
            return [
                item
                for item in args
                if (
                    (isinstance(item, str) and item.startswith("_"))
                    or item is None
                    or item == ""
                )
            ]

        # For any other iterable type, attempt to iterate
        return [
            item
            for item in args
            if (
                (isinstance(item, str) and item.startswith("_"))
                or item is None
                or item == ""
            )
        ]
    except Exception:
        # In case of unexpected errors (e.g., non-iterable input), return an empty list
        return []

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    # Basic validation
    if not isinstance(options_spec, (list, tuple)):
        raise TypeError("options_spec must be a list or tuple of option specifications")
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of received arguments")

    required_args = []

    for opt in options_spec:
        # Each option spec is expected to be a dict-like object
        if not isinstance(opt, dict):
            continue  # skip invalid spec
        name = opt.get("name")
        if not name:
            continue  # skip if no name

        cond = opt.get("required_when")
        if cond is None:
            continue  # no conditional requirement

        # Evaluate condition
        try:
            match = False
            if callable(cond):
                # If condition is a callable, call it with args
                match = bool(cond(args))
            elif isinstance(cond, str):
                # Simple string condition parsing
                if "==" in cond:
                    key, val = cond.split("==", 1)
                    key = key.strip()
                    val = val.strip()
                    # Remove surrounding quotes if present
                    if (val.startswith("'") and val.endswith("'")) or (val.startswith('"') and val.endswith('"')):
                        val = val[1:-1]
                    match = str(args.get(key)) == val
                elif "!=" in cond:
                    key, val = cond.split("!=", 1)
                    key = key.strip()
                    val = val.strip()
                    if (val.startswith("'") and val.endswith("'")) or (val.startswith('"') and val.endswith('"')):
                        val = val[1:-1]
                    match = str(args.get(key)) != val
                else:
                    # Treat as presence check: option must be truthy
                    match = bool(args.get(cond))
            else:
                # Unsupported condition type; skip
                continue

            if match:
                required_args.append(name)
        except Exception:
            # If condition evaluation fails, ignore this option
            continue

    return required_args

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # Basic type check for args
        if args is None:
            raise TypeError("args cannot be None")
        if not isinstance(args, dict):
            raise TypeError("args must be a dictionary of argument names to values")

        # If the class does not define any choices mapping, nothing to validate
        choices_map = getattr(self, "choices", None)
        if not isinstance(choices_map, dict):
            return

        for arg_name, arg_value in args.items():
            # Skip arguments that have no defined choices
            if arg_name not in choices_map:
                continue

            allowed = choices_map[arg_name]
            if allowed is None:
                continue

            # Ensure the allowed set is iterable
            try:
                iter(allowed)
            except TypeError:
                # If allowed is not iterable, skip validation for this argument
                continue

            # Helper to validate a single value
            def _check_value(val):
                if val not in allowed:
                    raise ValueError(
                        f"Invalid value '{val}' for argument '{arg_name}'. "
                        f"Allowed values: {sorted(allowed)}"
                    )

            # If the argument value is an iterable (but not a string), validate each element
            if isinstance(arg_value, (list, tuple, set)):
                for v in arg_value:
                    _check_value(v)
            else:
                _check_value(arg_value)

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Retrieve the minimum and maximum bounds from the instance.
    try:
        min_val = getattr(self, "min_value")
        max_val = getattr(self, "max_value")
    except AttributeError as exc:
        raise AttributeError(
            "Instance must define 'min_value' and 'max_value' attributes."
        ) from exc

    # Ensure the bounds are numeric and logically consistent.
    if not isinstance(min_val, (int, float)) or not isinstance(max_val, (int, float)):
        raise TypeError("min_value and max_value must be numeric.")
    if min_val > max_val:
        raise ValueError("min_value cannot be greater than max_value.")

    # Normalise the input into an iterable of values.
    if args is None:
        raise ValueError("args cannot be None.")
    if isinstance(args, dict):
        values = args.values()
    elif isinstance(args, (list, tuple, set)):
        values = args
    else:
        # Treat a single non-iterable value as a one-element iterable.
        values = [args]

    # Validate each value.
    for val in values:
        if not isinstance(val, (int, float)):
            raise TypeError(f"Argument value {val!r} is not numeric.")
        if val < min_val or val > max_val:
            raise ValueError(
                f"Argument value {val!r} is outside the allowed range "
                f"[{min_val}, {max_val}]."
            )

    return True

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of strings")
    control_args = {}
    nested_args = {}
    for arg in args:
        if not isinstance(arg, str):
            continue
        # Split key and value
        if "=" in arg:
            key, val = arg.split("=", 1)
        else:
            key, val = arg, True
        # Normalize key by stripping leading dashes
        key = key.lstrip("-")
        if not key:
            continue
        # Determine if this is a control argument
        if key.startswith("control.") or key.startswith("control_") or key.startswith("control-"):
            control_args[key] = val
        else:
            nested_args[key] = val
    return control_args, nested_args

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        :return: The updated dictionary
        """
        # Validate input types
        if not isinstance(vars_dict, dict):
            raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")
        if extra_vars is None:
            return vars_dict
        if not isinstance(extra_vars, (list, tuple)):
            raise TypeError(f"extra_vars must be a list or tuple, got {type(extra_vars).__name__}")

        for item in extra_vars:
            # Skip non-string items
            if not isinstance(item, str):
                continue
            # Expect format key=value
            if '=' not in item:
                continue
            key, value = item.split('=', 1)
            key = key.strip()
            value = value.strip()
            if not key:
                continue
            # Attempt to interpret value as JSON if possible
            try:
                import json
                parsed = json.loads(value)
                value = parsed
            except Exception:
                # Keep as string if JSON parsing fails
                pass
            vars_dict[key] = value

        return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Import required modules locally to avoid global imports
    import subprocess
    import json
    import os

    # Basic type checks
    if not isinstance(playbook_path, str):
        raise TypeError("playbook_path must be a string")
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook file not found: {playbook_path}")

    if verbose is not None:
        if not isinstance(verbose, int) or verbose < 0:
            raise ValueError("verbose must be a non-negative integer")
    if extra_vars is not None and not isinstance(extra_vars, dict):
        raise TypeError("extra_vars must be a dict if provided")
    if ansible_args is not None and not isinstance(ansible_args, dict):
        raise TypeError("ansible_args must be a dict if provided")

    # Build the command
    cmd = ["ansible-playbook", playbook_path]

    # Verbosity
    if verbose:
        cmd.append("-" + "v" * verbose)

    # Extra vars
    if extra_vars:
        try:
            json_str = json.dumps(extra_vars)
        except (TypeError, ValueError) as e:
            raise ValueError(f"Failed to serialize extra_vars to JSON: {e}")
        cmd.extend(["--extra-vars", json_str])

    # Additional ansible arguments
    if ansible_args:
        for key, value in ansible_args.items():
            if not isinstance(key, str):
                raise TypeError(f"ansible_args keys must be strings, got {type(key)}")
            if isinstance(value, bool):
                if value:
                    cmd.append(f"--{key}")
                # if False, skip adding the flag
            else:
                cmd.extend([f"--{key}", str(value)])

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False,
        )
    except FileNotFoundError as e:
        raise RuntimeError("ansible-playbook executable not found") from e
    except Exception as e:
        raise RuntimeError(f"Error running ansible-playbook: {e}") from e

    # If the command failed, raise an error with output
    if result.returncode != 0:
        raise RuntimeError(
            f"ansible-playbook failed with exit code {result.returncode}\n"
            f"Stdout:\n{result.stdout}\nStderr:\n{result.stderr}"
        )

    return result

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        # Optional parser‑specific type mapping (extend as needed)
        parser_specific = {
            # Example:
            # 'virsh': {'timeout': int, 'debug': bool},
            # 'ospd': {'port': int, 'verbose': bool},
        }

        type_map = parser_specific.get(parser_name, {})

        for key, val in list(values_dict.items()):
            # Skip non‑string values
            if not isinstance(val, str):
                continue

            # Apply parser‑specific conversion if defined
            if key in type_map:
                try:
                    values_dict[key] = type_map[key](val)
                except Exception:
                    # Keep original string if conversion fails
                    pass
                continue

            v = val.strip()
            if v == '':
                continue

            # None
            if v.lower() == 'none':
                values_dict[key] = None
                continue

            # Boolean
            if v.lower() in ('true', 'false'):
                values_dict[key] = v.lower() == 'true'
                continue

            # Integer
            if v.isdigit() or (v.startswith('-') and v[1:].isdigit()):
                try:
                    values_dict[key] = int(v)
                    continue
                except Exception:
                    pass

            # Float
            try:
                f = float(v)
                values_dict[key] = f
                continue
            except Exception:
                pass

            # List (comma separated)
            if ',' in v:
                try:
                    lst = [item.strip() for item in v.split(',')]
                    values_dict[key] = lst
                    continue
                except Exception:
                    pass

            # Default: keep as string
        # No explicit return needed; values_dict is modified in place.

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    from pathlib import Path

    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    # Validate plugin_dir
    try:
        p_dir = Path(plugin_dir)
    except Exception as exc:
        raise ValueError(f"Invalid plugin_dir path: {plugin_dir}") from exc

    if not p_dir.is_dir():
        raise FileNotFoundError(f"Plugin directory not found: {plugin_dir}")

    # Find spec file (yaml or json)
    spec_file = None
    for ext in ("yaml", "yml", "json"):
        candidate = p_dir / f"plugin.{ext}"
        if candidate.is_file():
            spec_file = candidate
            break
    if spec_file is None:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    # Load spec
    try:
        with spec_file.open("r", encoding="utf-8") as f:
            if spec_file.suffix in {".yaml", ".yml"}:
                try:
                    import yaml
                except ImportError as exc:
                    raise ImportError("PyYAML is required to parse YAML plugin specs") from exc
                data = yaml.safe_load(f)
            else:  # .json
                data = json.load(f)
    except Exception as exc:
        raise ValueError(f"Failed to load plugin spec from {spec_file}: {exc}") from exc

    if not isinstance(data, dict):
        raise ValueError(f"Plugin spec must be a mapping, got {type(data).__name__}")

    # Flatten and return
    return _flatten(data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    try:
        import os
        env_var = "CONFIG_PATH"
        if env_var not in os.environ:
            # Default to a config file in the current working directory
            default_path = os.path.join(os.getcwd(), "config.yaml")
            os.environ[env_var] = default_path
    except Exception as exc:
        raise RuntimeError(f"Unable to set configuration environment variable: {exc}") from exc
